function env_shared(name: string): string | undefined {
  const v = Deno.env.get(name);
  return v && v.trim() ? v.trim() : undefined;
}

interface AuthUser {
  id: string;
  email?: string;
}

async function getUser(req: Request): Promise<AuthUser | null> {
  const auth = req.headers.get("Authorization");
  const url = env_shared("SUPABASE_URL");
  const anon = env_shared("SUPABASE_ANON_KEY");
  if (!auth || !url || !anon) return null;
  const res = await fetch(`${url}/auth/v1/user`, { headers: { Authorization: auth, apikey: anon } });
  if (!res.ok) return null;
  return (await res.json()) as AuthUser;
}

function serviceHeaders(): Record<string, string> | null {
  const service = env_shared("SUPABASE_SERVICE_ROLE_KEY");
  if (!service) return null;
  return { apikey: service, Authorization: `Bearer ${service}`, "Content-Type": "application/json" };
}

async function getPlan(userId: string): Promise<"free" | "premium" | "family"> {
  const url = env_shared("SUPABASE_URL");
  const headers = serviceHeaders();
  if (!url || !headers) return "free";
  const res = await fetch(
    `${url}/rest/v1/subscriptions?user_id=eq.${encodeURIComponent(userId)}&select=plan,status,current_period_end`,
    { headers },
  );
  if (!res.ok) return "free";
  const rows = (await res.json()) as { plan: string; status: string; current_period_end: string | null }[];
  const sub = rows[0];
  if (!sub) return "free";
  const live = ["active", "trialing", "past_due"].includes(sub.status);
  const notExpired = !sub.current_period_end || new Date(sub.current_period_end) > new Date();
  if (!live || !notExpired) return "free";
  return sub.plan === "family" ? "family" : sub.plan === "premium" ? "premium" : "free";
}

function countUsageThisMonth(userId: string, kind: string): Promise<number> {
  const now = new Date();
  return countUsageSince(userId, kind, new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1)).toISOString());
}

/** Usage in the last 24 hours (a rolling "day" that ignores time zones). */
function countUsageToday(userId: string, kind: string): Promise<number> {
  return countUsageSince(userId, kind, new Date(Date.now() - 24 * 3600_000).toISOString());
}

async function countUsageSince(userId: string, kind: string, since: string): Promise<number> {
  const url = env_shared("SUPABASE_URL");
  const headers = serviceHeaders();
  if (!url || !headers) return 0;
  const res = await fetch(
    `${url}/rest/v1/ai_usage?user_id=eq.${encodeURIComponent(userId)}&kind=eq.${encodeURIComponent(kind)}&created_at=gte.${encodeURIComponent(since)}&select=id`,
    { headers: { ...headers, Prefer: "count=exact", Range: "0-0" } },
  );
  const range = res.headers.get("content-range"); // e.g. "0-0/3" or "*/0"
  const total = range?.split("/")[1];
  return total && total !== "*" ? Number(total) : 0;
}

async function recordUsage(userId: string, kind: string): Promise<void> {
  const url = env_shared("SUPABASE_URL");
  const headers = serviceHeaders();
  if (!url || !headers) return;
  await fetch(`${url}/rest/v1/ai_usage`, {
    method: "POST",
    headers: { ...headers, Prefer: "return=minimal" },
    body: JSON.stringify({ user_id: userId, kind }),
  });
}

/** True when the user is listed in `app_admins`. */
async function isAdminUser(userId: string): Promise<boolean> {
  const url = env_shared("SUPABASE_URL");
  const headers = serviceHeaders();
  if (!url || !headers) return false;
  const res = await fetch(`${url}/rest/v1/app_admins?user_id=eq.${encodeURIComponent(userId)}&select=user_id`, {
    headers,
  });
  if (!res.ok) return false;
  return ((await res.json()) as unknown[]).length > 0;
}

// ── inlined from supabase/functions/_shared/recipe-image.ts ──
/**
 * AI food photos for recipes: one prompt style for the whole library, stored in
 * the public `recipe-images` bucket and saved on recipes.image_path.
 *
 * Secrets: OPENAI_API_KEY. Optional: IMAGE_MODEL (default gpt-image-1-mini),
 * IMAGE_QUALITY (low | medium | high, default medium).
 */

const IMAGE_BUCKET = "recipe-images";
const IMAGE_SIZE = "1536x1024";

function secret(name: string): string | undefined {
  const v = Deno.env.get(name);
  return v && v.trim() ? v.trim() : undefined;
}

function imageModel(): { model: string; quality: string } {
  return { model: secret("IMAGE_MODEL") ?? "gpt-image-1-mini", quality: secret("IMAGE_QUALITY") ?? "medium" };
}

function buildImagePrompt(r: { name: string; cuisine?: string | null; details?: string | null }): string {
  return [
    `Professional overhead-angle food photograph of ${r.name}${r.cuisine ? `, a ${r.cuisine} dish` : ""}, freshly made at home.`,
    r.details ? `The dish: ${r.details}` : "",
    "Served in a handmade ceramic dish on a warm walnut wooden table with a soft linen napkin;",
    "warm natural window light, soft shadows, shallow depth of field, rich appetising colours, realistic textures,",
    "earthy warm palette of walnut brown, soft linen beige, sage green and muted gold.",
    "Halal food only: no pork, no wine or alcohol in the scene.",
    "No text, no logos, no watermark, no people, no hands.",
  ]
    .filter(Boolean)
    .join(" ");
}

function imageSlug(s: string) {
  return s.toLowerCase().normalize("NFKD").replace(/[̀-ͯ]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 60);
}

async function generateFoodImage(apiKey: string, prompt: string, model: string, quality: string): Promise<ArrayBuffer> {
  const res = await fetch("https://api.openai.com/v1/images/generations", {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${apiKey}` },
    // gpt-image models can return compressed WebP directly (much smaller files).
    body: JSON.stringify({ model, prompt, size: IMAGE_SIZE, quality, n: 1, output_format: "webp", output_compression: 82 }),
  });
  if (!res.ok) {
    const text = await res.text();
    console.error(`OpenAI images ${res.status}: ${text.slice(0, 500)}`);
    const err = new Error(
      res.status === 429 && /quota|billing/i.test(text)
        ? "The OpenAI account is out of credit."
        : res.status === 429
          ? "OpenAI rate limit — waiting a moment."
          : res.status === 400 && /safety|moderation/i.test(text)
            ? "OpenAI declined this prompt."
            : `OpenAI error ${res.status}.`,
    ) as Error & { status?: number };
    err.status = res.status;
    throw err;
  }
  const data = (await res.json()) as { data?: { b64_json?: string }[] };
  const b64 = data.data?.[0]?.b64_json;
  if (!b64) throw new Error("OpenAI returned no image.");
  return Uint8Array.from(atob(b64), (c) => c.charCodeAt(0)).buffer as ArrayBuffer;
}

function toBase64(bytes: ArrayBuffer): string {
  const arr = new Uint8Array(bytes);
  let binary = "";
  const CHUNK = 0x8000;
  for (let i = 0; i < arr.length; i += CHUNK) {
    binary += String.fromCharCode(...arr.subarray(i, i + CHUNK));
  }
  return btoa(binary);
}

/**
 * Asks a vision model whether the generated photo plausibly shows the dish.
 * Returns ok=false with a short reason when it clearly does not (for example
 * a beef stew rendered with shrimp). Throws when the check itself cannot run,
 * so callers can decide whether to keep the photo or not.
 */
async function photoMatchesDish(
  apiKey: string,
  imageBytes: ArrayBuffer,
  dishName: string,
): Promise<{ ok: boolean; reason: string }> {
  const res = await fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${apiKey}` },
    body: JSON.stringify({
      model: "gpt-4o-mini",
      max_tokens: 40,
      messages: [
        {
          role: "user",
          content: [
            {
              type: "text",
              text: `This photo was generated for a recipe called "${dishName}". Does the photo plausibly show this dish? Reply with exactly one line: YES or NO, followed by a very short reason (max 10 words).`,
            },
            { type: "image_url", image_url: { url: `data:image/webp;base64,${toBase64(imageBytes)}` } },
          ],
        },
      ],
    }),
  });
  if (!res.ok) throw new Error(`Vision check failed ${res.status}`);
  const data = (await res.json()) as { choices?: { message?: { content?: string } }[] };
  const text = (data.choices?.[0]?.message?.content ?? "").trim();
  return { ok: /^yes\b/i.test(text), reason: text.slice(0, 120) || "no reason given" };
}

/**
 * Generates a food photo and verifies it shows the right dish, retrying with
 * a corrected prompt when the vision check says it does not. Throws when no
 * attempt passes, so a wrong photo is never saved (the recipe simply keeps
 * no photo and can be retried later). When the vision check itself errors,
 * the photo is kept rather than blocking generation.
 */
async function generateVerifiedFoodImage(
  apiKey: string,
  model: string,
  quality: string,
  dish: { name: string; cuisine?: string | null; details?: string | null },
  maxAttempts = 3,
): Promise<ArrayBuffer> {
  let lastReason = "";
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    const prompt =
      buildImagePrompt(dish) +
      (attempt > 1 && lastReason
        ? ` IMPORTANT: the previous attempt was wrong (${lastReason}). Show exactly the dish described above and nothing else.`
        : "");
    const bytes = await generateFoodImage(apiKey, prompt, model, quality);
    try {
      const check = await photoMatchesDish(apiKey, bytes, dish.name);
      if (check.ok) return bytes;
      lastReason = check.reason;
      console.error(`Photo check failed for "${dish.name}" (attempt ${attempt}/${maxAttempts}): ${check.reason}`);
    } catch (err) {
      console.error(`Photo check unavailable for "${dish.name}": ${err instanceof Error ? err.message : err}`);
      return bytes;
    }
  }
  throw new Error(`No correct photo for "${dish.name}" after ${maxAttempts} attempts (last: ${lastReason}).`);
}

async function uploadFoodImage(path: string, bytes: ArrayBuffer): Promise<string> {
  const url = secret("SUPABASE_URL")!;
  const key = secret("SUPABASE_SERVICE_ROLE_KEY")!;
  const res = await fetch(`${url}/storage/v1/object/${IMAGE_BUCKET}/${path}`, {
    method: "POST",
    headers: { apikey: key, Authorization: `Bearer ${key}`, "Content-Type": "image/webp", "x-upsert": "true", "Cache-Control": "31536000" },
    body: bytes,
  });
  if (!res.ok) throw new Error(`Upload failed ${res.status}: ${(await res.text()).slice(0, 200)}`);
  return `${url}/storage/v1/object/public/${IMAGE_BUCKET}/${path}`;
}

/**
 * Makes a photo for each recipe that has none yet, one at a time, until the
 * time budget runs out. Recipes left over are picked up by the admin
 * "Recipe images" tool or the next plan that uses them.
 */
async function photographRecipes(ids: string[], budgetMs = 120_000): Promise<void> {
  const apiKey = secret("OPENAI_API_KEY");
  const url = secret("SUPABASE_URL");
  const key = secret("SUPABASE_SERVICE_ROLE_KEY");
  const unique = [...new Set(ids)].filter((id) => /^[0-9a-f-]{36}$/i.test(id));
  if (!apiKey || !url || !key || !unique.length) return;
  const headers = { apikey: key, Authorization: `Bearer ${key}`, "Content-Type": "application/json" };
  const res = await fetch(
    `${url}/rest/v1/recipes?select=id,name,short_description,image_prompt,cuisine:cuisines(name)&image_path=is.null&id=in.(${unique.join(",")})`,
    { headers },
  );
  if (!res.ok) return;
  const rows = (await res.json()) as { id: string; name: string; short_description: string | null; image_prompt: string | null; cuisine: { name: string } | null }[];
  const { model, quality } = imageModel();
  const stopAt = Date.now() + budgetMs;
  for (const r of rows) {
    if (Date.now() > stopAt) break;
    try {
      const dish = { name: r.name, cuisine: r.cuisine?.name, details: r.image_prompt ?? r.short_description };
      const bytes = await generateVerifiedFoodImage(apiKey, model, quality, dish);
      const path = `${imageSlug(r.name)}-${r.id.slice(0, 8)}-${Date.now().toString(36)}.webp`;
      const image = await uploadFoodImage(path, bytes);
      await fetch(`${url}/rest/v1/recipes?id=eq.${r.id}&image_path=is.null`, {
        method: "PATCH",
        headers: { ...headers, Prefer: "return=minimal" },
        body: JSON.stringify({ image_path: image }),
      });
    } catch (err) {
      const e = err as Error & { status?: number };
      console.error(`Recipe photo for ${r.name}: ${e.message}`);
      if (e.status === 429 || e.status === 401) break;
    }
  }
}

// ── inlined from supabase/functions/_shared/recipe-translate.ts ──
// AI chef recipes in French and Arabic. English stays the master copy (pantry,
// shopping and allergy checks match on English names); this writes the
// translations into recipe_translations / food_translations — same recipe id,
// same photo, only the words change.

type Lang = "en" | "fr" | "ar";
const OTHER_LANGS: Exclude<Lang, "en">[] = ["fr", "ar"];

const MODEL_shared = "gpt-4o-mini";

interface TranslatableMeal {
  id?: string;
  name: string;
  description: string;
  ingredients: { name: string }[];
  recipe: string[];
}

interface Translated {
  name: string;
  description: string;
  steps: string[];
  ingredients: string[];
}

const LANG_NAME = { fr: "French", ar: "Arabic (Modern Standard, simple everyday words)" } as const;

/** The language the person is using, from the request (defaults to English). */
function requestLang(value: unknown): Lang {
  return value === "fr" || value === "ar" ? value : "en";
}

async function translateOne(apiKey: string, meal: TranslatableMeal, lang: "fr" | "ar"): Promise<Translated | null> {
  const source = {
    name: meal.name,
    description: meal.description,
    steps: meal.recipe,
    ingredients: meal.ingredients.map((i) => i.name),
  };
  const res = await fetchOpenAI(apiKey, {
    model: MODEL_shared,
    temperature: 0.2,
    max_tokens: 2500,
    response_format: { type: "json_object" },
    messages: [
      {
        role: "system",
        content:
          `You translate halal family recipes from English into ${LANG_NAME[lang]} for a cooking app. ` +
          "Keep dish names that are known by their own name (tajine, biryani, shawarma…) in their usual form for that language. " +
          "Keep every number, temperature and quantity exactly. Keep the same number of steps and ingredients, in the same order. " +
          'Return JSON {"name": string, "description": string, "steps": string[], "ingredients": string[]}.',
      },
      { role: "user", content: JSON.stringify(source) },
    ],
  });
  if (!res.ok) return null;
  try {
    const data = (await res.json()) as { choices?: { message?: { content?: string } }[] };
    const t = JSON.parse(data.choices?.[0]?.message?.content ?? "{}") as Partial<Translated>;
    const okList = (a: unknown, n: number) => Array.isArray(a) && a.length === n && a.every((s) => typeof s === "string" && s.trim());
    if (typeof t.name !== "string" || !t.name.trim()) return null;
    return {
      name: t.name.trim(),
      description: typeof t.description === "string" ? t.description.trim() : "",
      steps: okList(t.steps, source.steps.length) ? (t.steps as string[]) : [],
      ingredients: okList(t.ingredients, source.ingredients.length) ? (t.ingredients as string[]) : [],
    };
  } catch {
    return null;
  }
}

/** Which of these library recipes already have a translation in this language. */
async function alreadyTranslated(url: string, headers: Record<string, string>, ids: string[], lang: string): Promise<Set<string>> {
  if (!ids.length) return new Set();
  try {
    const res = await fetch(`${url}/rest/v1/recipe_translations?select=recipe_id&lang=eq.${lang}&recipe_id=in.(${ids.join(",")})`, { headers });
    const rows = res.ok ? ((await res.json()) as { recipe_id: string }[]) : [];
    return new Set(rows.map((r) => r.recipe_id));
  } catch {
    return new Set();
  }
}

/**
 * Translates the library meals into one language, saves the result, and returns
 * the English → translated words (for the app to show straight away).
 */
async function translateMeals(apiKey: string, meals: TranslatableMeal[], lang: "fr" | "ar"): Promise<Record<string, string>> {
  const url = Deno.env.get("SUPABASE_URL");
  const key = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  const words: Record<string, string> = {};
  if (!url || !key) return words;
  const headers = { apikey: key, Authorization: `Bearer ${key}`, "Content-Type": "application/json" };
  const isId = (id?: string): id is string => typeof id === "string" && /^[0-9a-f-]{36}$/i.test(id);
  // One translation per recipe, even if the plan has it twice.
  const unique = [...new Map(meals.filter((m) => isId(m.id)).map((m) => [m.id!, m])).values()];
  const done = await alreadyTranslated(url, headers, unique.map((m) => m.id!), lang);
  const todo = unique.filter((m) => !done.has(m.id!));
  if (!todo.length) return words;

  const results = await Promise.all(todo.map((m) => translateOne(apiKey, m, lang).catch(() => null)));
  const recipeRows: Record<string, unknown>[] = [];
  const foodRows: { name_en: string; lang: string; name: string }[] = [];
  todo.forEach((m, i) => {
    const t = results[i];
    if (!t) return;
    recipeRows.push({ recipe_id: m.id, lang, name: t.name, short_description: t.description || null, steps: t.steps });
    words[m.name] = t.name;
    if (m.description && t.description) words[m.description] = t.description;
    m.recipe.forEach((s, j) => t.steps[j] && (words[s] = t.steps[j]));
    m.ingredients.forEach((ing, j) => {
      const name = t.ingredients[j];
      if (!name) return;
      words[ing.name] = name;
      const en = ing.name.trim().toLowerCase();
      if (en.length <= 120 && name.length <= 120) foodRows.push({ name_en: en, lang, name });
    });
  });
  try {
    if (recipeRows.length) {
      await fetch(`${url}/rest/v1/rpc/save_recipe_translations`, { method: "POST", headers, body: JSON.stringify({ rows: recipeRows }) });
    }
    if (foodRows.length) {
      // Only names the library doesn't know yet: the reviewed list stays as it is.
      const known = await fetch(
        `${url}/rest/v1/food_translations?select=name_en&lang=eq.${lang}&name_en=in.(${encodeURIComponent(foodRows.map((f) => `"${f.name_en.replace(/"/g, "")}"`).join(","))})`,
        { headers },
      )
        .then((r) => (r.ok ? (r.json() as Promise<{ name_en: string }[]>) : []))
        .catch(() => [] as { name_en: string }[]);
      const have = new Set(known.map((k) => k.name_en));
      const fresh = [...new Map(foodRows.filter((f) => !have.has(f.name_en)).map((f) => [f.name_en, f])).values()];
      if (fresh.length) {
        await fetch(`${url}/rest/v1/rpc/save_food_translations`, { method: "POST", headers, body: JSON.stringify({ rows: fresh }) });
      }
    }
  } catch (e) {
    console.error("Saving translations failed", e);
  }
  return words;
}

/**
 * Translates new AI chef meals into French and Arabic. The person's own
 * language is awaited (so the reply already carries it); the other keeps
 * going after the reply is sent.
 */
async function translateForPlan(apiKey: string, meals: TranslatableMeal[], lang: Lang): Promise<Record<string, string>> {
  const runtime = (globalThis as { EdgeRuntime?: { waitUntil(p: Promise<unknown>): void } }).EdgeRuntime;
  let mine: Promise<Record<string, string>> = Promise.resolve({});
  for (const other of OTHER_LANGS) {
    const task = translateMeals(apiKey, meals, other).catch((e) => {
      console.error(`Translating to ${other} failed`, e);
      return {} as Record<string, string>;
    });
    if (other === lang) mine = task;
    else runtime?.waitUntil(task);
  }
  return await mine;
}

// ── recipe-fill ──
/**
 * Fills the recipe library so every combination of filters a family can pick
 * has at least TARGET recipes, for every meal type and every cuisine.
 *
 * How: a recipe free of every allergen Firdam offers, and vegan and
 * gluten-free, fits ANY mix of allergy and diet filters, except the three
 * that a dish must positively be (high-protein, low-carb, kid-friendly). So for
 * each meal type × cuisine × mix of those three, the library needs TARGET such
 * "free-from-everything" recipes. This function counts what is missing and
 * writes the missing recipes (with nutrition, tags, French and Arabic, and a photo).
 * A new recipe stays hidden (is_active = false) until its photo is made:
 * families never see a recipe without its picture.
 *
 *   POST { action: "status" }        → how many slots still need recipes
 *   POST { action: "fill", limit? }  → writes up to `limit` (1–3) recipes
 *
 * Allowed for Firdam admins, or with header x-lunchbox-token (the Vault secret
 * "lunchbox_admin_token", used by the database job "recipe-fill").
 */

const MODEL = "gpt-4o-mini";
const TARGET = 3;
const MEALS = ["breakfast", "lunch", "dinner", "snack"] as const;
/** Every allergy the filters offer (Milk = dairy, Wheat = gluten). */
const ALL_ALLERGIES = ["Celery", "Eggs", "Fish", "Gluten", "Lupin", "Milk", "Mustard", "Peanuts", "Sesame", "Shellfish", "Soy", "Sulphites", "Tree nuts", "Wheat"];
const FREE_DIETS = ["Vegetarian", "Vegan", "Gluten-free", "Dairy-free", "Pescatarian"];
const EXTRAS = ["High-protein", "Low-carb", "Kid-friendly"] as const;
/** Things the word matcher can't see for Lupin and Sulphites. */
const HIDDEN = /\b(lupin|lupini|sulphite|sulfite|vinegar|wine|dried apricots?|dried fruit|raisins?|sultanas?|molasses|pickled|pickles?|mustard)\b/i;

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization, X-Client-Info, Apikey, x-lunchbox-token",
};
const json = (body: unknown, status = 200) => new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });
const env = (n: string) => {
  const v = Deno.env.get(n);
  return v && v.trim() ? v.trim() : undefined;
};

async function rest<T>(path: string, init: RequestInit = {}): Promise<T> {
  const url = env("SUPABASE_URL")!;
  const key = env("SUPABASE_SERVICE_ROLE_KEY")!;
  const res = await fetch(`${url}/rest/v1/${path}`, {
    ...init,
    headers: { apikey: key, Authorization: `Bearer ${key}`, "Content-Type": "application/json", ...(init.headers ?? {}) },
  });
  if (!res.ok) throw new Error(`Database ${res.status}: ${(await res.text()).slice(0, 300)}`);
  const text = await res.text();
  return (text ? JSON.parse(text) : null) as T;
}

interface Row {
  id: string;
  name: string;
  protein: number | null;
  carbs: number | null;
  cuisine: { name: string } | null;
  meal_type: { name: string } | null;
  recipe_ingredients: { ingredient: { name: string } | null }[];
  recipe_allergens: { allergen: { name: string } | null }[];
  recipe_tags: { tag: { name: string } | null }[];
}

const mealKey = (n: string | undefined | null) => {
  const s = (n ?? "").toLowerCase();
  return MEALS.find((m) => s.includes(m)) ?? null;
};

/** Free of every allergy Firdam offers, and vegan + gluten-free. */
function freeFromEverything(ings: string[], tagged: string[], tags: string[]): boolean {
  if (conflictsWithAllergies(ings, ALL_ALLERGIES, tagged)) return false;
  if (ings.some((i) => HIDDEN.test(i))) return false;
  return FREE_DIETS.every((d) => fitsDiet(d, { ingredients: ings, tags }));
}

/** Which of the three "must be" filters a recipe meets (bit 0 high-protein, 1 low-carb, 2 kid-friendly). */
function extrasMask(ings: string[], tags: string[], protein: number | null, carbs: number | null): number {
  return EXTRAS.reduce((m, d, i) => (fitsDiet(d, { ingredients: ings, tags, protein, carbs }) ? m | (1 << i) : m), 0);
}

interface Slot {
  meal: (typeof MEALS)[number];
  cuisine: string;
  extras: number;
  have: number;
}

/** Every meal × cuisine × mix of extras with fewer than TARGET fitting recipes, hardest first. */
async function findGaps(): Promise<{ gaps: Slot[]; cuisines: string[] }> {
  const rows: Row[] = [];
  for (let from = 0; ; from += 1000) {
    const page = await rest<Row[]>(
      `recipes?select=id,name,protein,carbs,cuisine:cuisines(name),meal_type:meal_types(name),recipe_ingredients(ingredient:ingredients(name)),recipe_allergens(allergen:allergens(name)),recipe_tags(tag:tags(name))&or=(is_active.eq.true,source.eq.ai-fill)&order=id`,
      { headers: { Range: `${from}-${from + 999}` } },
    );
    rows.push(...page);
    if (page.length < 1000) break;
  }
  const cuisines = Array.from(new Set(rows.map((r) => r.cuisine?.name).filter((c): c is string => !!c))).sort();
  // count[meal|cuisine|extras-mask-of-recipe]
  const free: Map<string, number[]> = new Map();
  for (const r of rows) {
    const meal = mealKey(r.meal_type?.name);
    const cuisine = r.cuisine?.name;
    if (!meal || !cuisine) continue;
    const ings = r.recipe_ingredients.map((x) => x.ingredient?.name ?? "").filter(Boolean);
    if (!ings.length) continue;
    const tagged = r.recipe_allergens.map((x) => x.allergen?.name ?? "").filter(Boolean);
    const tags = r.recipe_tags.map((x) => x.tag?.name ?? "").filter(Boolean);
    if (!freeFromEverything(ings, tagged, tags)) continue;
    const k = `${meal}|${cuisine}`;
    (free.get(k) ?? free.set(k, []).get(k)!).push(extrasMask(ings, tags, r.protein, r.carbs));
  }
  const skipped = new Set((await rest<{ key: string }[]>("recipe_fill_skips?select=key&tries=gte.3")).map((s) => s.key));
  const gaps: Slot[] = [];
  for (const meal of MEALS) {
    for (const cuisine of cuisines) {
      const masks = free.get(`${meal}|${cuisine}`) ?? [];
      for (let want = 0; want < 8; want++) {
        const have = masks.filter((m) => (m & want) === want).length;
        if (have < TARGET && !skipped.has(`${meal}|${cuisine}|${want}`)) gaps.push({ meal, cuisine, extras: want, have });
      }
    }
  }
  // Most extras first: one high-protein + low-carb + kid-friendly recipe also fills the easier mixes.
  gaps.sort((a, b) => bits(b.extras) - bits(a.extras) || a.have - b.have);
  return { gaps, cuisines };
}
const bits = (n: number) => (n & 1) + ((n >> 1) & 1) + ((n >> 2) & 1);

interface Written {
  name: string;
  description: string;
  type: string;
  cuisine: string;
  difficulty: string;
  prepTime: number;
  cookTime: number;
  servings: number;
  protein: number;
  carbs: number;
  calories: number;
  kidFriendly: boolean;
  ingredients: { name: string; quantity: string; unit: string }[];
  recipe: string[];
}

async function writeRecipe(slot: Slot, avoidNames: string[], problem: string | null): Promise<Written> {
  const apiKey = env("OPENAI_API_KEY");
  if (!apiKey) throw new Error("AI is not set up.");
  const wants = [
    slot.extras & 1 ? "high in protein: at least 25 g protein per serving (beans, lentils, chickpeas, quinoa, hemp or pumpkin seeds; NO soy, NO nuts)" : null,
    slot.extras & 2 ? "low-carb: at most 25 g carbohydrates per serving" : null,
    slot.extras & 4 ? "kid-friendly: mild, familiar, not spicy, easy for children to eat" : null,
  ].filter(Boolean);
  const res = await fetchOpenAI(apiKey, {
    model: MODEL,
    temperature: 0.8,
    response_format: { type: "json_object" },
    messages: [
      {
        role: "system",
        content: [
          "You write authentic, practical home recipes for Muslim families. Every rule below is a hard rule:",
          "- Halal. Vegan: no meat, poultry, fish, seafood, eggs, milk, butter, ghee, cheese, yoghurt, cream or honey.",
          "- NO gluten: no wheat, flour, bread, pasta, couscous, bulgur, freekeh, semolina, barley, rye, spelt, soy sauce. Use rice, corn, potatoes, quinoa, buckwheat, millet, gluten-free oats, rice paper, corn tortillas.",
          "- NO peanuts, NO tree nuts (almonds, cashews, pistachios, walnuts, coconut is fine), NO sesame or tahini, NO soy (tofu, tempeh, edamame, miso), NO mustard, NO celery, NO lupin.",
          "- NO sulphites: no vinegar, wine, dried apricots, raisins or other dried fruit, pickles or molasses. Use lemon or lime juice for sourness.",
          "- No alcohol, no vanilla extract (vanilla powder is fine).",
          "- Name every ingredient plainly (e.g. 'red lentils', 'olive oil'). Quantities for the servings given.",
          "- Honest nutrition per serving.",
        ].join("\n"),
      },
      {
        role: "user",
        content:
          `Write one ${slot.cuisine} ${slot.meal} recipe that really tastes ${slot.cuisine}.` +
          (wants.length ? ` It must be ${wants.join("; ")}.` : "") +
          ` Do not repeat: ${avoidNames.slice(0, 40).join("; ")}.` +
          (problem ? ` The last try was rejected because it ${problem}. Fix that.` : "") +
          ` Answer as JSON: {"name":"","description":"one sentence","difficulty":"Easy|Medium","prepTime":minutes,"cookTime":minutes,"servings":4,` +
          `"protein":grams per serving,"carbs":grams per serving,"calories":per serving,"kidFriendly":true|false,` +
          `"ingredients":[{"name":"","quantity":"","unit":""}],"recipe":["step", "..."]}`,
      },
    ],
  });
  if (!res.ok) throw new Error((await describeOpenAIFailure(res)).message);
  const data = (await res.json()) as { choices?: { message?: { content?: string } }[] };
  const o = JSON.parse(data.choices?.[0]?.message?.content ?? "{}") as Record<string, unknown>;
  const num = (v: unknown, d = 0) => (Number.isFinite(Number(v)) ? Number(v) : d);
  return {
    name: String(o.name ?? "").trim().slice(0, 120),
    description: String(o.description ?? "").trim().slice(0, 300),
    type: slot.meal[0].toUpperCase() + slot.meal.slice(1),
    cuisine: slot.cuisine,
    difficulty: String(o.difficulty ?? "Easy"),
    prepTime: Math.round(num(o.prepTime, 10)),
    cookTime: Math.round(num(o.cookTime, 20)),
    servings: Math.max(1, Math.round(num(o.servings, 4))),
    protein: num(o.protein),
    carbs: num(o.carbs),
    calories: num(o.calories),
    kidFriendly: o.kidFriendly === true,
    ingredients: (Array.isArray(o.ingredients) ? o.ingredients : [])
      .map((x) => x as Record<string, unknown>)
      .map((x) => ({ name: String(x.name ?? "").trim().slice(0, 80), quantity: String(x.quantity ?? "").trim().slice(0, 20), unit: String(x.unit ?? "").trim().slice(0, 20) }))
      .filter((x) => x.name)
      .slice(0, 25),
    recipe: (Array.isArray(o.recipe) ? o.recipe : []).map((s) => String(s).trim().slice(0, 600)).filter(Boolean).slice(0, 15),
  };
}

/** Why a written recipe doesn't fill the slot, or null when it does. */
function problemWith(w: Written, slot: Slot): string | null {
  if (w.name.length < 3 || w.ingredients.length < 3 || w.recipe.length < 2) return "was incomplete";
  const ings = w.ingredients.map((i) => i.name);
  const halal = haramReason(ings, w.recipe);
  if (halal) return `was not halal (${halal})`;
  const tags = w.kidFriendly ? ["kid-friendly"] : [];
  if (!freeFromEverything(ings, [], tags)) return "contained an allergen, gluten or an animal product";
  const mask = extrasMask(ings, tags, w.protein, w.carbs);
  if ((mask & slot.extras) !== slot.extras) {
    const missing = EXTRAS.filter((_, i) => slot.extras & (1 << i) && !(mask & (1 << i)));
    return `was not ${missing.join(" and ").toLowerCase()}`;
  }
  return null;
}

async function tagIds(names: string[]): Promise<string[]> {
  const ids: string[] = [];
  for (const name of names) {
    const found = await rest<{ id: string }[]>(`tags?select=id&name=ilike.${encodeURIComponent(name)}&limit=1`);
    if (found[0]) ids.push(found[0].id);
    else ids.push((await rest<{ id: string }[]>("tags", { method: "POST", headers: { Prefer: "return=representation" }, body: JSON.stringify({ name }) }))[0].id);
  }
  return ids;
}

async function save(w: Written): Promise<string | null> {
  const before = await rest<{ id: string }[]>(`recipes?select=id&name=ilike.${encodeURIComponent(w.name)}&limit=1`);
  if (before.length) return null; // same name already in the library
  const id = await rest<string | null>("rpc/save_ai_recipe", { method: "POST", body: JSON.stringify({ meal: w }) });
  if (!id) return null;
  await rest(`recipes?id=eq.${id}`, {
    method: "PATCH",
    headers: { Prefer: "return=minimal" },
    // Hidden until its photo is made (see showPhotographed).
    body: JSON.stringify({ protein: w.protein, carbs: w.carbs, calories: w.calories, source: "ai-fill", is_active: false }),
  });
  const tags = ["Vegetarian", "Vegan", "Gluten-free", "Dairy-free", "Nut-free", ...(w.kidFriendly ? ["Kid-friendly"] : []), ...(w.protein >= 25 ? ["High-protein"] : []), ...(w.carbs <= 25 ? ["Low-carb"] : [])];
  const ids = await tagIds(tags);
  await rest("recipe_tags?on_conflict=recipe_id,tag_id", {
    method: "POST",
    headers: { Prefer: "resolution=ignore-duplicates,return=minimal" },
    body: JSON.stringify(ids.map((tag_id) => ({ recipe_id: id, tag_id }))),
  });
  return id;
}

/** Makes photos for filler recipes still waiting for one, then shows the ones that have it. */
async function photographAndShow(newIds: string[], budgetMs: number) {
  const waiting = await rest<{ id: string }[]>("recipes?select=id&source=eq.ai-fill&is_active=eq.false&image_path=is.null&order=created_at&limit=6");
  const ids = Array.from(new Set([...newIds, ...waiting.map((w) => w.id)]));
  if (ids.length) await photographRecipes(ids, budgetMs);
  await rest("recipes?source=eq.ai-fill&is_active=eq.false&image_path=not.is.null", {
    method: "PATCH",
    headers: { Prefer: "return=minimal" },
    body: JSON.stringify({ is_active: true }),
  });
}

async function skip(slot: Slot, error: string) {
  const key = `${slot.meal}|${slot.cuisine}|${slot.extras}`;
  const prev = await rest<{ tries: number }[]>(`recipe_fill_skips?select=tries&key=eq.${encodeURIComponent(key)}`);
  await rest("recipe_fill_skips?on_conflict=key", {
    method: "POST",
    headers: { Prefer: "resolution=merge-duplicates,return=minimal" },
    body: JSON.stringify({ key, tries: (prev[0]?.tries ?? 0) + 1, last_error: error.slice(0, 300), updated_at: new Date().toISOString() }),
  });
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { status: 200, headers: corsHeaders });
  if (req.method !== "POST") return json({ error: "Use POST." }, 405);
  try {
    const token = req.headers.get("x-lunchbox-token");
    const allowed = token
      ? (await rest<boolean>("rpc/check_lunchbox_admin_token", { method: "POST", body: JSON.stringify({ p_token: token }) })) === true
      : await (async () => {
          const user = await getUser(req);
          return !!user && (await isAdminUser(user.id));
        })();
    if (!allowed) return json({ error: "Admins only." }, 403);

    const body = (await req.json().catch(() => ({}))) as Record<string, unknown>;
    const { gaps, cuisines } = await findGaps();
    if (body.action !== "fill") {
      return json({ remaining: gaps.length, cuisines: cuisines.length, sample: gaps.slice(0, 12).map((g) => `${g.cuisine} ${g.meal} [${EXTRAS.filter((_, i) => g.extras & (1 << i)).join(", ") || "any"}] has ${g.have}`) });
    }

    const limit = Math.min(3, Math.max(1, Number(body.limit) || 1));
    const apiKey = env("OPENAI_API_KEY")!;
    const made: string[] = [];
    const ids: string[] = [];
    const stopAt = Date.now() + 70_000;
    for (const slot of gaps.slice(0, limit)) {
      if (Date.now() > stopAt) break;
      const avoid = await rest<{ name: string }[]>(`recipes?select=name&cuisine_id=not.is.null&source=eq.ai-fill&order=created_at.desc&limit=40`).then((r) => r.map((x) => x.name)).catch(() => []);
      let problem: string | null = null;
      let saved: string | null = null;
      for (let attempt = 0; attempt < 2 && !saved; attempt++) {
        try {
          const w = await writeRecipe(slot, avoid, problem);
          problem = problemWith(w, slot);
          if (problem) continue;
          saved = await save(w);
          if (!saved) problem = "had a name already in the library";
          else {
            made.push(`${w.name} (${slot.cuisine} ${slot.meal})`);
            ids.push(saved);
            for (const lang of ["fr", "ar"] as const) {
              await translateMeals(apiKey, [{ id: saved, name: w.name, description: w.description, ingredients: w.ingredients, recipe: w.recipe }], lang).catch((e) => console.error("translate", e));
            }
          }
        } catch (e) {
          problem = (e as Error).message;
          console.error("recipe-fill", slot, problem);
        }
      }
      if (!saved) await skip(slot, problem ?? "unknown");
    }
    // Photos after the response, so the database job isn't kept waiting.
    // deno-lint-ignore no-explicit-any
    (globalThis as any).EdgeRuntime?.waitUntil?.(photographAndShow(ids, 120_000).catch((e) => console.error("photos", e)));
    return json({ made, remaining: Math.max(0, gaps.length - made.length) });
  } catch (e) {
    console.error(e);
    return json({ error: (e as Error).message }, 500);
  }
});
